/**
 * A runtime-validation schema library, declared the way the real ones are.
 *
 * A schema has TWO types, and they differ wherever parsing changes the value
 * (carrick#1101):
 *
 *  - the OUTPUT, what `parse` returns and what a handler receives, exposed as
 *    the `parse` return type and the `_output` member;
 *  - the INPUT, what a caller is allowed to send, exposed as the `_input`
 *    member and as the Standard Schema member `~standard.types.input` (whose
 *    `types` is optional, as the specification declares it).
 *
 * `defaulted` makes a key optional to send and required after parsing,
 * `transform` changes the member's type, and `coerce.number()` accepts any
 * value on input. `optional` has the same shape both ways. `parseOnly` is a
 * schema that exposes nothing but `parse`, so only its output is knowable.
 */

export interface StandardTypes<Input, Output> {
  readonly input: Input;
  readonly output: Output;
}

export interface StandardProps<Input, Output> {
  readonly version: 1;
  readonly vendor: string;
  readonly types?: StandardTypes<Input, Output> | undefined;
}

/** What a non-throwing parse hands back: the output, or the failure. */
export type SafeParseResult<Output> =
  | { readonly success: true; readonly data: Output }
  | { readonly success: false; readonly error: { readonly message: string } };

export interface Schema<Output, Input = Output> {
  parse(data: unknown): Output;
  safeParse(data: unknown): SafeParseResult<Output>;
  readonly _output: Output;
  readonly _input: Input;
  readonly '~standard': StandardProps<Input, Output>;
}

export interface OptionalSchema<Output, Input = Output>
  extends Schema<Output | undefined, Input | undefined> {
  readonly __optional: true;
}

export interface DefaultedSchema<Output, Input = Output>
  extends Schema<Output, Input | undefined> {
  readonly __defaulted: true;
}

type AnySchema = Schema<unknown, unknown>;

type OutputOf<S> = S extends Schema<infer Output, unknown> ? Output : never;
type InputOf<S> = S extends { readonly _input: infer Input } ? Input : never;

type OutputOptionalKeys<Shape> = {
  [K in keyof Shape]: Shape[K] extends OptionalSchema<unknown, unknown> ? K : never;
}[keyof Shape];

type InputOptionalKeys<Shape> = {
  [K in keyof Shape]: Shape[K] extends
    | OptionalSchema<unknown, unknown>
    | DefaultedSchema<unknown, unknown>
    ? K
    : never;
}[keyof Shape];

/** Homomorphic, so the `?` modifiers survive the flattening. */
type Flatten<T> = { [K in keyof T]: T[K] };

type ObjectOutput<Shape extends Record<string, AnySchema>> = Flatten<
  { [K in Exclude<keyof Shape, OutputOptionalKeys<Shape>>]: OutputOf<Shape[K]> } & {
    [K in OutputOptionalKeys<Shape>]?: OutputOf<Shape[K]>;
  }
>;

type ObjectInput<Shape extends Record<string, AnySchema>> = Flatten<
  { [K in Exclude<keyof Shape, InputOptionalKeys<Shape>>]: InputOf<Shape[K]> } & {
    [K in InputOptionalKeys<Shape>]?: InputOf<Shape[K]>;
  }
>;

export declare function object<Shape extends Record<string, AnySchema>>(
  shape: Shape
): Schema<ObjectOutput<Shape>, ObjectInput<Shape>>;
export declare function string(): Schema<string>;
export declare function number(): Schema<number>;
export declare function boolean(): Schema<boolean>;
export declare function array<Item extends AnySchema>(
  item: Item
): Schema<OutputOf<Item>[], InputOf<Item>[]>;
export declare function pair<First extends AnySchema, Second extends AnySchema>(
  first: First,
  second: Second
): Schema<[OutputOf<First>, OutputOf<Second>], [InputOf<First>, InputOf<Second>]>;
export declare function optional<Inner extends AnySchema>(
  inner: Inner
): OptionalSchema<OutputOf<Inner>, InputOf<Inner>>;
export declare function defaulted<Inner extends AnySchema>(
  inner: Inner,
  value: OutputOf<Inner>
): DefaultedSchema<OutputOf<Inner>, InputOf<Inner>>;
export declare function transform<Inner extends AnySchema, Out>(
  inner: Inner,
  fn: (value: OutputOf<Inner>) => Out
): Schema<Out, InputOf<Inner>>;
export declare const coerce: {
  number(): Schema<number, unknown>;
};
export declare function parseOnly<Output>(): { parse(data: unknown): Output };
